"""Build a small SYNTHETIC workbook so the tool can be tried without private data.

Usage: python -m sentinel_review.demo demo.xlsx
Every name, code and value here is invented. None of it is Kestrel data or clinical guidance.
"""
import sys
from pathlib import Path
from openpyxl import Workbook

SHEETS = {
    "00_README": [["note"], ["SYNTHETIC demo workbook generated by sentinel_review.demo. Contains no real data."]],
    "01_Excursion_Events": [
        ["event_id", "alert_ts_utc", "tenant_code", "product_ref_as_received", "excursion_start_utc", "min_temp_c",
         "max_temp_c", "logger_fw", "regulator_reportable", "reg_window_hours", "triage_outcome", "final_disposition"],
        ["DEMO-1", "2026-03-10 08:20", "T-DEMO-A", "08900000000017", "2026-03-10 08:00", 5.0, 11.0, "TT-2.14.3",
         "N", None, "ACTIONABLE", "RELEASE_WITH_NOTE"],
        ["DEMO-2", "2026-03-11 09:05", "T-DEMO-A", "08900000000017", "2026-03-11 09:00", None, None, "X-1.0",
         "N", None, "ACTIONABLE", None],
        ["DEMO-3", "2026-03-12 10:10", "T-DEMO-B", "Demoflu Q", "2026-03-12 10:00", 1.0, 9.0, "X-1.0",
         "Y", 72, "ACTIONABLE", None],
    ],
    "02_Product_Master": [
        ["tenant_code", "brand_as_labelled", "generic_inn", "internal_sku", "gtin", "legacy_code",
         "permitted_excursion_text", "stability_study_ref"],
        ["T-DEMO-A", "Demo Pen 100U", "democillin-x", "SKU-DEMO-1", "08900000000017", None,
         "Cumulative 10 h above 8 C (synthetic)", "STB-D2"],
        ["T-DEMO-B", "Demoflu Q", "flu-demo", "SKU-DEMO-2", "08900000000024", None, None, "STB-D9"],
    ],
    "05_SOP_Index": [
        ["doc_id", "tenant_code", "title", "revision", "effective_from", "effective_to"],
        ["SOP-D-1", "T-DEMO-A", "Temperature Excursion Management", "Rev 01", "2025-01-01", "2026-06-30"],
        ["SOP-D-1", "T-DEMO-A", "Temperature Excursion Management", "Rev 02", "2026-01-01", None],
        ["SOP-D-2", "T-DEMO-B", "Temperature Excursion Management", "Rev 01", "2025-01-01", None],
    ],
    "06_Stability_Index": [
        ["study_ref", "product_text_as_written", "tenant_code", "study_type", "permitted_excursion_text", "readable"],
        ["STB-D1", "Demo Pen 100U pen", "T-DEMO-A", "Excursion / thermal cycling",
         "One excursion, up to 2 h below 12 C (synthetic)", "Y"],
        ["STB-D2", "Demo Pen vial democillin-x", "T-DEMO-A", "Accelerated", None, "Partial"],
        ["STB-D3", "Demo Pen 100U vial", "T-DEMO-A", "Excursion / thermal cycling",
         "No excursion above 20 C (synthetic)", "Y"],
        ["STB-D9", "Demoflu Q", "T-DEMO-B", "Excursion", "Synthetic text only", "Y"],
    ],
}


def build_demo_workbook(path):
    book = Workbook()
    book.remove(book.active)
    for name, rows in SHEETS.items():
        sheet = book.create_sheet(name)
        for row in rows:
            sheet.append(row)
    book.save(path)
    return Path(path)


def main():
    if len(sys.argv) != 2:
        raise SystemExit("usage: python -m sentinel_review.demo OUTPUT.xlsx")
    print(build_demo_workbook(sys.argv[1]))


if __name__ == "__main__":
    main()
